using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

// Builds Moku's materials, prefab and a preview scene from Moku.fbx
// (generated by Tools/Blender/build_moku.py). Safe to re-run; it overwrites its own outputs.
public static class MokuModelBuilder
{
    const string ModelPath = "Assets/Models/Characters/Moku.fbx";
    const string AtlasPath = "Assets/Models/Characters/Textures/MokuAtlas.png";
    const string MaterialDir = "Assets/Models/Characters/Materials/Moku";
    const string PrefabDir = "Assets/Prefabs/Characters";
    const string PrefabPath = PrefabDir + "/Moku.prefab";
    const string ScenePath = "Assets/Scenes/MokuPreview.unity";

    // Textured materials are white: their colors come from the atlas.
    static readonly (string name, Color color, bool textured)[] MaterialDefs =
    {
        ("MokuSkin", Color.white, true),
        ("MokuShirt", Color.white, true),
        ("MokuJacket", Color.white, true),
        ("MokuWarmer", Color.white, true),
        ("MokuHair", Color.white, true),         // black above, blue below, split in the atlas
        ("MokuHairBlue", Color.white, true),
        ("MokuHorn", new Color(0.85f, 0.06f, 0.08f), false),
        ("MokuEar", new Color(0.07f, 0.07f, 0.08f), false),
        ("MokuLine", new Color(0.02f, 0.02f, 0.02f), false),
        ("MokuMetal", new Color(0.66f, 0.66f, 0.68f), false),
        ("MokuGold", new Color(0.85f, 0.65f, 0.20f), false),
        ("MokuGem", new Color(0.80f, 0.04f, 0.07f), false),
        ("MokuLining", new Color(0.62f, 0.04f, 0.06f), false),
        ("MokuSkirt", new Color(0.05f, 0.05f, 0.06f), false),
        ("MokuBoot", new Color(0.08f, 0.08f, 0.09f), false),
    };

    // The outline hulls are exported with flipped faces, so back-face culling leaves only their inside
    // showing behind the silhouette: a plain black line, unaffected by light.
    const string OutlineMaterial = "MokuOutline";

    [MenuItem("Tools/Moku/Rebuild Prefab")]
    public static void Build()
    {
        AssetDatabase.Refresh(); // pick up a freshly exported FBX/atlas
        EnsureFolder(MaterialDir);
        EnsureFolder(PrefabDir);
        CreateMaterials();
        ConfigureImporter();

        var model = AssetDatabase.LoadAssetAtPath<GameObject>(ModelPath);
        var instance = (GameObject)PrefabUtility.InstantiatePrefab(model);
        instance.name = "Moku";
        var prefab = PrefabUtility.SaveAsPrefabAsset(instance, PrefabPath);
        Object.DestroyImmediate(instance);

        BuildPreviewScene(prefab);
        AssetDatabase.SaveAssets();
        Debug.Log("[Moku] Rebuilt materials, prefab and preview scene.");
    }

    static void CreateMaterials()
    {
        var atlasImporter = (TextureImporter)AssetImporter.GetAtPath(AtlasPath);
        atlasImporter.mipmapEnabled = false;
        atlasImporter.filterMode = FilterMode.Point;
        atlasImporter.wrapMode = TextureWrapMode.Clamp;
        atlasImporter.SaveAndReimport();
        var atlas = AssetDatabase.LoadAssetAtPath<Texture2D>(AtlasPath);

        var lit = Shader.Find("Universal Render Pipeline/Lit");
        foreach (var (name, color, textured) in MaterialDefs)
        {
            var mat = LoadOrCreate(name, lit);
            mat.shader = lit;
            mat.SetColor("_BaseColor", color);
            mat.SetTexture("_BaseMap", textured ? atlas : null);
            mat.SetFloat("_Smoothness", 0f);
            mat.SetFloat("_EnvironmentReflections", 0f);
            mat.EnableKeyword("_ENVIRONMENTREFLECTIONS_OFF");
            mat.SetFloat("_SpecularHighlights", 0f);
            mat.EnableKeyword("_SPECULARHIGHLIGHTS_OFF");
            EditorUtility.SetDirty(mat);
        }

        var outline = LoadOrCreate(OutlineMaterial, Shader.Find("Universal Render Pipeline/Unlit"));
        outline.shader = Shader.Find("Universal Render Pipeline/Unlit");
        outline.SetColor("_BaseColor", new Color(0.02f, 0.02f, 0.02f));
        outline.SetFloat("_Cull", 2f); // back
        EditorUtility.SetDirty(outline);
    }

    static Material LoadOrCreate(string name, Shader shader)
    {
        var path = $"{MaterialDir}/{name}.mat";
        var mat = AssetDatabase.LoadAssetAtPath<Material>(path);
        if (mat == null)
        {
            mat = new Material(shader);
            AssetDatabase.CreateAsset(mat, path);
        }
        return mat;
    }

    static void ConfigureImporter()
    {
        var importer = (ModelImporter)AssetImporter.GetAtPath(ModelPath);
        importer.animationType = ModelImporterAnimationType.None;
        importer.importAnimation = false;
        importer.importCameras = false;
        importer.importLights = false;
        importer.importBlendShapes = false;
        importer.importNormals = ModelImporterNormals.Import; // flat facets come from the FBX

        // FBX slot names match the material names.
        foreach (var remap in importer.GetExternalObjectMap().Keys.ToList())
            importer.RemoveRemap(remap);
        foreach (var name in MaterialDefs.Select(d => d.name).Append(OutlineMaterial))
            importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material), name),
                AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{name}.mat"));
        importer.SaveAndReimport();
    }

    static void BuildPreviewScene(GameObject prefab)
    {
        var scene = EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects, NewSceneMode.Single);

        // Moku faces +Z, so the camera looks back at her from the +Z side.
        var cam = Camera.main.transform;
        cam.SetPositionAndRotation(new Vector3(0f, 0.45f, 1.6f), Quaternion.Euler(5f, 180f, 0f));
        var sun = Object.FindFirstObjectByType<Light>();
        if (sun != null)
            sun.transform.rotation = Quaternion.Euler(40f, 160f, 0f);

        var ground = GameObject.CreatePrimitive(PrimitiveType.Plane);
        ground.name = "Ground";
        ground.transform.localScale = new Vector3(0.3f, 1f, 0.3f);

        PrefabUtility.InstantiatePrefab(prefab);
        EditorSceneManager.SaveScene(scene, ScenePath);
    }

    static void EnsureFolder(string path)
    {
        if (AssetDatabase.IsValidFolder(path))
            return;
        var parent = System.IO.Path.GetDirectoryName(path).Replace('\\', '/');
        EnsureFolder(parent);
        AssetDatabase.CreateFolder(parent, System.IO.Path.GetFileName(path));
    }
}
